export const ItemById = Object.fromEntries(Items.map(e => [e.id, e]));
export const ItemGroupByType = Items.reduce((acc, e) => {
    if (e.type != null) {
        let arr = e.type;
        if (!Array.isArray(arr)) { arr = [arr]; }
        arr.forEach(group => {
            if (!acc[group]) {
                acc[group] = [];
            }
            acc[group].push(e);
        })
    }
    return acc;
}, {})
